code.python:
class Solution:
    def sum(self, num1: int, num2: int) -> int:
        MASK = 0xFFFFFFFF
        MAX_INT = 0x7FFFFFFF
        num1 &= MASK
        num2 &= MASK
        while num2 != 0:
            carry = ((num1 & num2) << 1) & MASK
            num1 = (num1 ^ num2) & MASK
            num2 = carry
        return num1 if num1 <= MAX_INT else ~(num1 ^ MASK)

